{queues.map((q) => (
  <div
    key={q._id}
    style={{
      background: "white",
      padding: "15px",
      borderRadius: "10px",
      marginBottom: "10px",
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center"
    }}
  >

    <h3>Token #{q.tokenNumber}</h3>

    <p>{q.patientName}</p>

    <p>{q.status}</p>

  </div>
))}
